import base64,hashlib,json,os,pathlib
os.umask(0o077)
out=pathlib.Path('/home/qian-qi/heptabao-kv2-ha-convergence-20261106-r1/build-test-4bde9-diagnostic-r11')
out.mkdir(mode=0o700)
items=[{"name":"controller.py","bytes":28356,"sha256":"7d993c47271ce2d9dd84b64bb925770122559d2e0296dc9a12a2728a39962855","base64":""},{"name":"test-selection.public.json","bytes":58485,"sha256":"c83414bbbca10f860a8b9b1355933c42b0a05f35c9b9dab95079253e8144494c","base64":""},{"name":"candidate.bundle","bytes":1393,"sha256":"9808cfef28ce90733b636e81aed122aeeaf4fe81e0f34b1b84dde7e0ab0e11cd","base64":""}]
for item in items:
 b=base64.b64decode(item['base64'],validate=True)
 assert len(b)==item['bytes'] and hashlib.sha256(b).hexdigest()==item['sha256']
 with (out/item['name']).open('xb') as f:
  f.write(b);f.flush();os.fsync(f.fileno())
assert (out/'candidate.bundle').is_file()
